-- Study Abroad country content, BATCH 23: Bolivia, Paraguay, Venezuela, Guatemala, Honduras, El Salvador, Nicaragua, Dominican Republic, Haiti, Guyana.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('bolivia', 'paraguay', 'venezuela', 'guatemala', 'honduras', 'el-salvador', 'nicaragua', 'dominican-republic', 'haiti', 'guyana'));
UPDATE countries SET why_title = 'Why study in Bolivia?', why_body = '<p>Bolivia offers low-cost Spanish-taught degrees at public and private universities, with strengths in medicine, dentistry and the social sciences, in a country of high-altitude landscapes and Andean culture.<ul><li>Low tuition and living costs</li><li>Spanish immersion</li><li>Strong in medicine and dentistry</li><li>Andean culture and landscapes</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Regular students get a <strong>student visa</strong> (reported at 60 days initial, with a temporary residence permit for up to three years); exchange students get 180 days. Sources differ, so confirm with DIGEMIG.</p><ul><li>Admission letter from a Bolivian institution</li><li>Passport valid at least six months, application and proof of fee payment</li><li>Financial proof of solvency and a criminal record certificate</li><li>Visa fee reported at US$50 for regular students (New Delhi embassy); no fee for state-agreement exchange</li><li>No clear information on student work rights</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official DIGEMIG and the Bolivian consulate site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Public universities such as UMSA publish admission calls and tests in Spanish (for example the PSA admission exam for 2027 ran on 4 October and 8 November 2026 for dentistry).</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public universities typically charge low or no tuition, though international students may pay more.</p><ul><li>No official UMSA international fee schedule was found</li><li>Private universities charge fees; check each</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'bolivia';
UPDATE countries SET why_title = 'Why study in Paraguay?', why_body = '<p>Paraguay is popular with medical students on a budget, with private universities offering Spanish-taught medicine and health degrees at low cost.<ul><li>Low tuition and living costs</li><li>Medicine and health programmes at private universities</li><li>Spanish and Guaraní culture</li><li>Stable, welcoming country</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Paraguay has no separate student visa. Students who stay beyond a visitor stay need <strong>temporary residence</strong> from the National Migration Directorate (DNM), plus a consular visa depending on nationality. Student temporary residence is reported as renewable yearly.</p><ul><li>Admission letter from a Paraguayan institution</li><li>Medical certificate (embassy guidance: original and one notarised copy, from a general practitioner)</li><li>No set proof-of-funds amount in the law; the Indian embassy asks for three months of bank statements</li><li>The residency money test changed in July 2026 for residency generally; confirm for students</li><li>Beware of fraudsters offering admission or visa packages through unofficial agents; verify acceptance letters with the university</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official DNM Paraguay, the Paraguayan consulate and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university; UNA publishes its fees (aranceles) on its website.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs vary by institution.</p><ul><li>Guide estimate: maximum monthly spending of about US$600 for an international student</li><li>Private medical schools: check each university schedule</li><li>UNA fee schedule: see its website</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'paraguay';
UPDATE countries SET why_title = 'Why study in Venezuela?', why_body = '<p>Venezuela has long-established public universities, but current conditions make study very difficult.<ul><li>Established public and private universities</li><li>Spanish immersion</li><li>Low or no tuition at public universities (reported)</li><li>No English-taught degrees found in official sources</li></ul></p><p>Canada advises against all travel to Venezuela, the US State Department lists Level 3 (Reconsider Travel) and the UK advises against all but essential travel to most of the country. Official guidance suggests postponing study plans.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A student visa is generally required for stays over 90 days and must be applied for before departure at a Venezuelan consulate. Consular services are limited or suspended in some countries.</p><ul><li>Admission letter from a Venezuelan institution</li><li>Aggregator figures (unverified): about US$70 fee, US$1,000 minimum funds and about 20 business days processing</li><li>Public universities have been reported as extremely disrupted</li><li>No official scholarship programme for international students found</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Venezuelan consulate and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public universities reportedly charge no or very low tuition, but arrangements vary.</p><ul><li>Living cost estimates range from US$200 to US$600 a month (unverified)</li><li>Check university fee schedules directly</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'venezuela';
UPDATE countries SET why_title = 'Why study in Guatemala?', why_body = '<p>Guatemala offers low-cost Spanish-taught degrees at Universidad de San Carlos and private universities, plus Spanish-language immersion in Antigua.<ul><li>Low tuition and living costs</li><li>Spanish language schools and immersion</li><li>Mayan culture and heritage</li><li>Public and private universities</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A student visa is needed, depending on nationality, and for a degree foreign students also need a <strong>temporary residence for students</strong> from the Guatemalan Migration Institute (IGM). Visa-exempt countries include the US and UK; Indian citizens need a consular visa.</p><ul><li>Admission letter from a Guatemalan university</li><li>Proof of university enrolment and financial resources</li><li>Government fee reported at GTQ 50 and a financial proof of about US$5,000 (secondary sources)</li><li>USAC publishes a specific list of requirements for foreign-diploma holders</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official IGM Guatemala and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees vary between sources.</p><ul><li>USAC: students from outside Latin America reportedly pay Q24,000 a year; a partial exemption can be requested</li><li>Another aggregator gives about US$2,005 a year for the Guatemala City campus; check the USAC fee table</li><li>Living costs: about US$400-$800 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'guatemala';
UPDATE countries SET why_title = 'Why study in Honduras?', why_body = '<p>Honduras offers very low-cost public university study at UNAH and private options, with Spanish-taught programmes and agriculture strengths at Zamorano.<ul><li>Very low tuition at public universities</li><li>Spanish immersion</li><li>Zamorano as a leading agricultural university</li><li>Rich biodiversity</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>International students need a <strong>temporary residence visa for students</strong>. Fees conflict across sources, so confirm with the consulate or the Honduran immigration authority.</p><ul><li>Admission letter from a Honduran university</li><li>Fee reported as HNL 50 (government) or US$30-$60 (embassy in Canada); these may be different fee types</li><li>The student visa is not a job-seeking visa</li><li>Rules change frequently; verify with dnm.gob.hn</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Honduran Migration Institute (dnm.gob.hn) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>UNAH requires its vocational test and the PHUMA admissions exam, which is available online for students living outside Honduras.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public universities are very cheap; private universities cost much more.</p><ul><li>UNAH: about US$50 a year for public tuition (unverified for international students); vocational test plus PHUMA reported at L500</li><li>Private universities such as Unitec: about US$7,000 a year (one source)</li><li>Living costs: about US$350-$700 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'honduras';
UPDATE countries SET why_title = 'Why study in El Salvador?', why_body = '<p>El Salvador offers low-cost Spanish-taught degrees at public and private universities, with merit and need-based scholarships at several institutions.<ul><li>Low tuition and living costs</li><li>Spanish immersion</li><li>Public and private universities</li><li>Scholarships at several universities</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>The rules split between a nationality-based consular visa and <strong>temporary residence for study</strong> from the DGME. One guide reports an initial 12-month stay that does not lead directly to permanent residence.</p><ul><li>Admission letter from a Salvadoran university</li><li>Passport, photographs and proof of funds</li><li>Part-time work reported as possible if it does not interfere with student status (DGME form F-10)</li><li>Official English-language visa pages are limited; check with the consulate</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official DGME El Salvador and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Sources conflict on fees.</p><ul><li>Public universities: roughly US$200-$800 a year (guide) or US$2,000-$4,000 for international students (another guide)</li><li>UES free tuition applies to students who finished secondary school in El Salvador</li><li>Living costs: about US$400-$700 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'el-salvador';
UPDATE countries SET why_title = 'Why study in Nicaragua?', why_body = '<p>Nicaragua has public and private universities teaching in Spanish at low cost; recent entry-rule changes and travel advisories need careful checking.<ul><li>Low tuition and living costs</li><li>Spanish immersion</li><li>Public and private universities</li><li>Natural landscapes</li></ul></p><p>One source reports that as of 18 October 2026 the US State Department advises Americans to reconsider travel (Level 3). Confirm on travel.state.gov and your own government''s advice.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Degree students apply to the DGME for <strong>temporary residence in the student subcategory</strong>. Provision 002-2026 (in force 16 February 2026) updated the list of countries needing a visa and reportedly removed visa on arrival for many nationalities.</p><ul><li>Admission letter and proof of financial support</li><li>Application form reported at NIO 109.87 (DGME, 2026)</li><li>Stays over six months generally need a student residence visa</li><li>Other sources report 60-month validity and a fee of 195; unverified</li><li>Check whether your nationality is affected by the 2026 changes</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official DGME Nicaragua and the Nicaraguan embassy site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official tuition figures or government scholarships for international students were found.</p><ul><li>Ask each university''s international office for fees</li><li>Living costs: about US$350-$700 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'nicaragua';
UPDATE countries SET why_title = 'Why study in Dominican Republic?', why_body = '<p>The Dominican Republic has many private universities offering Spanish-taught degrees, and medicine is one of its largest subjects, with some English-taught options.<ul><li>Medicine and health programmes at private universities</li><li>Caribbean location</li><li>Spanish immersion</li><li>Tourism and business sectors</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Foreign students need a <strong>student visa (E)</strong> from a Dominican consulate and a <strong>student permit (E-1)</strong> from immigration after arrival. The visa is described as one year and multiple entry.</p><ul><li>Admission letter from a Dominican university</li><li>Health insurance valid in the Dominican Republic and approved by DGM for the whole study period</li><li>Proof of financial solvency and a DGM-authorised medical examination</li><li>Criminal record certificate</li><li>Visa fee: US$100 (MIREX), €172 or 400 (unspecified) in different sources</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official DGM, the Dominican consulate and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official 2026 tuition schedules were found.</p><ul><li>Medicine: US$4,000-$10,000 a year (recruitment guide; unverified)</li><li>MESCyT scholarships are for Dominican citizens only</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'dominican-republic';
UPDATE countries SET why_title = 'Why study in Haiti?', why_body = '<p>Haiti has public and private universities, but security conditions are extremely severe and international study is not currently advisable.<ul><li>Université d''État d''Haïti and private institutions</li><li>French and Creole-language education</li><li>No student-specific information was found for 2026</li></ul></p><p>Official governments advise against all travel to Haiti. This page is informational only and does not recommend travel.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No student visa guidance was found in this research. Travel advisories are the dominant factor: the US lists Level 4 (Do Not Travel) with an advisory dated July 2026, Canada advises avoiding all travel, and Ireland advises against travel.</p><ul><li>US commercial flights to Port-au-Prince are not operating (July 2026 update)</li><li>The Dominican Republic reopened its air border on 30 May 2026; land and sea borders remain closed</li><li>Check your government''s advice and the Haitian embassy before any plans</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official the Haitian embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>No admission information was found; contact the universities directly.</p><ul><li>Academic transcripts and certificates</li><li>French language proof</li><li>Entrance exam at public universities</li><li>Passport copy and photographs</li><li>Check each university''s status and safety</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No tuition figures were found.</p><ul><li>Contact the universities directly for fees</li><li>Living costs: not estimated because of conditions</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'haiti';
UPDATE countries SET why_title = 'Why study in Guyana?', why_body = '<p>Guyana is an English-speaking South American country with the University of Guyana, and a fast-growing economy driven by oil and gas.<ul><li>English-medium teaching</li><li>Oil and gas, agriculture and mining sectors</li><li>Rainforest and wildlife</li><li>Caribbean community links</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>You apply for a student visa online through ISS eServices and it is issued on arrival, with a school acceptance letter uploaded as a mandatory document (Guyana High Commission, London).</p><ul><li>School acceptance letter</li><li>Passport and photographs</li><li>Ministry of Home Affairs student visa documents do not mention permission to work; ask Immigration Support Services</li><li>Confirm current permit requirements before you travel</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Immigration Support Services Guyana and the University of Guyana site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>For Semester 2 of 2026-27 the University of Guyana''s online applications run 1 December 2026 to 9 January 2027; Semester 1 began on 31 August 2026.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Payment due by the commencement date of the semester</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees apply to non-Guyanese students only, since Guyanese tuition is government-funded from 1 January 2025.</p><ul><li>International undergraduate: US$5,711 a year for most programmes and US$8,853 for MBBS (guide and WHED); postgraduate US$5,711-$10,000</li><li>A Free-Apply page shows about US$2,624, which does not match the university figures</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (CSEC/CAPE or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'guyana';
COMMIT;
